changeSet.sql:
UPDATE system_message
SET translations = '{"uz": "Kiritilgan ma''lumotlar noto''g''ri", "en": "Some fields are invalid", "ru": "Введённые данные некорректны"}'::jsonb
WHERE code = 'error.validation.failed';

UPDATE system_message
SET translations = '{"uz": "Bu hisob Google orqali yaratilgan. «Google orqali kirish» tugmasidan foydalaning yoki profil sozlamalarida parol o''rnating", "en": "This account was created with Google. Use «Sign in with Google» or set a password in your profile settings", "ru": "Этот аккаунт создан через Google. Используйте «Войти через Google» или задайте пароль в настройках профиля"}'::jsonb
WHERE code = 'error.auth.password_not_set';
